-- Crear tabla PagosProveedor
CREATE TABLE PagosProveedor (
    pago_id VARCHAR(10) PRIMARY KEY,
    order_proveedor_id VARCHAR(10),
    provider_id VARCHAR(8),
    fecha_orden DATE,
    condicion_pago VARCHAR(20),
    fecha_vencimiento DATE,
    fecha_pago DATE,
    monto_total DECIMAL(12,2),
    estado_pago VARCHAR(20)
);

